from typing import TypeVar, overload


T = TypeVar("T")
K = TypeVar("K")

__all__ = ["bubble_sort"]


def _identity(value: T) -> T:
    return value


def _decorate_items(
    items: MutableSequence[T],
    key: Callable[[T], K],
) -> list[tuple[K, T]]:
    return [(key(item), item) for item in items]


def _bubble_sort_records(
    records: MutableSequence[tuple[K, T]],
    reverse: bool,
) -> None:
    for end in range(len(records) - 1, 0, -1):
        swapped = False
        for index in range(end):
            left_key = records[index][0]
            right_key = records[index + 1][0]
            should_swap = left_key < right_key if reverse else left_key > right_key

            if should_swap:
                records[index], records[index + 1] = records[index + 1], records[index]
                swapped = True

        if not swapped:
            break


